#!/usr/bin/env python3
"""Validates an SVG wireframe generated by the gerar-wireframes skill.

Usage:
    python3 validar_wireframe.py etapas/04_wireframes/wireframe_home-desktop.svg [others.svg ...]

Checks:
  - valid XML with an <svg> root, viewBox, data-pagina and data-viewport;
  - <title> and <desc> present;
  - each section is a <g class="secao"> with id, data-nome, data-layout and data-elementos;
  - unique section ids;
  - nothing copied or external: no <image>, <script>, <foreignObject>, external href
    or base64-embedded images.

Exit: 0 = ok, 1 = problems found.
"""
import sys
import xml.etree.ElementTree as ET

NS = "{http://www.w3.org/2000/svg}"
XLINK = "{http://www.w3.org/1999/xlink}href"
PROIBIDOS = {"image", "script", "foreignObject"}
ATRIBUTOS_SECAO = ("data-nome", "data-layout", "data-elementos")


def tag(el):
    return el.tag.replace(NS, "")


def validar(caminho):
    erros, avisos = [], []
    try:
        raiz = ET.parse(caminho).getroot()
    except (ET.ParseError, OSError) as e:
        return [f"could not read the SVG: {e}"], []

    if tag(raiz) != "svg":
        erros.append("the root is not <svg>")
    for attr in ("viewBox", "data-pagina", "data-viewport"):
        if not raiz.get(attr):
            erros.append(f"<svg> missing attribute {attr}")
    for filho in ("title", "desc"):
        if raiz.find(NS + filho) is None:
            erros.append(f"missing <{filho}> at the start of the file")

    ids = set()
    secoes = [g for g in raiz.iter(NS + "g") if "secao" in (g.get("class") or "").split()]
    if not secoes:
        erros.append('no section found (<g class="secao">)')
    for g in secoes:
        sid = g.get("id")
        if not sid:
            erros.append(f"section without id ({g.get('data-nome', '?')})")
        elif sid in ids:
            erros.append(f"duplicate section id: {sid}")
        ids.add(sid)
        for attr in ATRIBUTOS_SECAO:
            if not g.get(attr):
                erros.append(f"section '{sid}' missing {attr}")
        if not g.get("data-mobile") and raiz.get("data-viewport") == "desktop":
            avisos.append(f"section '{sid}' missing data-mobile (responsive behavior)")

    for el in raiz.iter():
        if tag(el) in PROIBIDOS:
            erros.append(f"forbidden element <{tag(el)}> (no images, scripts or embedded HTML)")
        href = el.get("href") or el.get(XLINK) or ""
        if href.startswith(("http:", "https:", "data:", "//")):
            erros.append(f"forbidden external or embedded reference: {href[:60]}")

    return erros, avisos


def main():
    # Avoids UnicodeEncodeError on Windows consoles (cp1252) when printing accents and symbols.
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    if len(sys.argv) < 2:
        print(__doc__)
        return 1
    falhou = False
    for caminho in sys.argv[1:]:
        erros, avisos = validar(caminho)
        status = "OK" if not erros else "PROBLEMS"
        print(f"{caminho}: {status}")
        for e in erros:
            print(f"  ✗ {e}")
        for a in avisos:
            print(f"  ! {a}")
        falhou = falhou or bool(erros)
    return 1 if falhou else 0


if __name__ == "__main__":
    sys.exit(main())
